ks_urls=[]
for d in KS_COUNTIES:
    sources=[
        ('Kansas Department of Health and Environment — Local Environmental Protection Program', KS_KDHE),
        ('KDHE Bulletin 4-2 — Minimum Standards for Onsite Wastewater Systems', KS_BULLETIN),
    ] + d['sources']
    sections=[
        ('Kansas uses local sanitary codes for onsite wastewater', 'KDHE states that local environmental programs adopted county sanitary codes emphasizing onsite wastewater systems and private wells. KDHE Bulletin 4-2 explains that sanitary codes are generally adopted and administered by local government and directs property owners to contact the local administering authority before investing in system design, plans, installation, or repairs. County requirements can be stricter than the state minimum standards.')
    ] + d['sections']
    ks_urls.append(write_county_page('Kansas','kansas',d['county'],d['authority'],d['contact'],sections,sources,verified='August 30, 2026'))

# Create a Kansas state hub using the same visual language as existing verified state hubs.
links=''.join(f'<li><a href="/counties/kansas/{slugify(d["county"])}/">{html.escape(d["county"])} County</a></li>' for d in sorted(KS_COUNTIES,key=lambda x:x['county']))
hub=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kansas Septic Permit Guides by County | SepticScope</title><meta name="description" content="Official-source Kansas septic permit guides by county."><link rel="canonical" href="https://septicscope.com/counties/kansas/"><style>{COMMON_STYLE}</style>{ga_tag}{adsense_tag}</head><body><header><div class="nav"><a class="brand" href="/">SepticScope</a></div></header><main><p><a href="/counties/">← All county guides</a></p><h1>Kansas septic permits by county</h1><p>Kansas relies heavily on local sanitary codes and local administering authorities for onsite wastewater. SepticScope adds Kansas counties only after the local authority and substantive local requirements are verified from government or public-health sources.</p><div class="note">This first Kansas batch covers Johnson, Sedgwick, and Douglas counties. Other Kansas counties remain on the nationwide lookup layer until their local program is individually validated.</div><h2>Choose a county</h2><ul class="grid">{links}</ul></main><footer><div>© 2026 SepticScope</div></footer></body></html>'''
hubdir=OUTPUT/'counties'/'kansas'; hubdir.mkdir(parents=True,exist_ok=True); (hubdir/'index.html').write_text(hub,encoding='utf-8')

county_index=OUTPUT/'counties'/'index.html'
if county_index.exists():
    text=county_index.read_text(encoding='utf-8')
    if '/counties/kansas/' not in text:
        promo='<section><h2>Kansas</h2><p><a href="/counties/kansas/">Browse the first 3 verified Kansas county septic guides →</a></p></section>'
        text=text.replace('</main>',promo+'</main>',1) if '</main>' in text else text.replace('</body>',promo+'</body>',1)
        county_index.write_text(text,encoding='utf-8')

# Add the hub and verified county URLs to the sitemap without duplicating existing entries.
sitemap=OUTPUT/'sitemap.xml'
new_urls=['https://septicscope.com/counties/kansas/']+ks_urls
if sitemap.exists():
    sm=sitemap.read_text(encoding='utf-8')
    entries=''.join(f'<url><loc>{u}</loc><lastmod>2026-08-30</lastmod></url>' for u in new_urls if u not in sm)
    if entries:
        sitemap.write_text(sm.replace('</urlset>',entries+'</urlset>'),encoding='utf-8')

# Production guard: validated county pages must not silently regress to nationwide fallback content.
for d in KS_COUNTIES:
    p=OUTPUT/'counties'/'kansas'/slugify(d['county'])/'index.html'
    t=p.read_text(encoding='utf-8')
    if 'Local septic rules not yet verified' in t or 'VERIFIED' not in t.upper() or 'Official sources' not in t:
        raise RuntimeError(f'Kansas verified page failed: {d["county"]}')

print(f'Kansas expansion complete: +{len(ks_urls)} verified county guides')
